package com.pythontopia.world.boss.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Pattern;

/** Client intent for starting a run; the map and gameplay state are generated by the server. */
public record ExpeditionRunStartRequest(
    @Min(1) @Max(7) Integer focusChapter,
    boolean isDaily,
    @Pattern(regexp = "PY43-KC-\\d{3}") String preferredKcCode) {}
